{"content":"from __future__ import annotations

import tarfile
import tempfile
from pathlib import Path


def install_bundle(archive_path: str | Path, destination: str | Path) -> list[str]:
    dest = Path(destination)
    with tempfile.TemporaryDirectory() as tmpdir:
        with tarfile.open(archive_path, "r:gz") as a:
            for member in a.getmembers():
                # Skip objects in tar files that should be ignored
                if not (member.isfile() or member.isdir()):
                    continue
                a.extract(member, tmpdir)
            # Return unique, sorted paths
            paths = sorted(set(Path(tmpdir, m.name) for m in a.getmembers()
                             if m.isfile() or m.isdir()))
            # Filter for regular files only as per callback contract
            return sorted([str(f) for f in paths if f.is_file()])
